int date_compare(const char *d1, const char *d2) {
    return strcmp(d1, d2);
}

int match(const char *str, const char *query) {
    if (strcmp(query, "*") == 0) return 1;
    return strstr(str, query) != NULL;
}

int main() {
    int n, q;
    Book books[MAX_BOOKS];

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%s %s %s", books[i].title, books[i].author, books[i].date);
    }

    scanf("%d", &q);
    char q_title[MAX_LEN], q_author[MAX_LEN], q_date_from[MAX_LEN], q_date_to[MAX_LEN];

    for (int i = 0; i < q; i++) {
        scanf("%s %s %s %s", q_title, q_author, q_date_from, q_date_to);

        int first_in_query = 1;
        for (int j = 0; j < n; j++) {
            if (match(books[j].title, q_title) &&
                match(books[j].author, q_author) &&
