import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        // Read number of books
        int n = Integer.parseInt(br.readLine().trim());

        // Store books
        List<Book> books = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String title = br.readLine().trim();
            String author = br.readLine().trim();
            String date = br.readLine().trim();
            books.add(new Book(title, author, date));
        }

        // Read number of queries
        int q = Integer.parseInt(br.readLine().trim());

        boolean firstQuery = true;
        for (int queryIdx = 0; queryIdx < q; queryIdx++) {
            String queryLine = br.readLine().trim();
            String[] parts = queryLine.split(" ");

            String qTitle = parts[0];
            String qAuthor = parts[1];
            String qDateFrom = parts[2];
            String qDateTo = parts[3];

            // Add blank line between queries (except before first)
            if (!firstQuery) {
                sb.append("\n");
            }
            firstQuery = false;

            boolean found = false;
            for (Book book : books) {
                if (matches(book, qTitle, qAuthor, qDateFrom, qDateTo)) {
                    if (found) {
                        sb.append("\n");
                    }
                    sb.append(book.title);
                    found = true;
                }
            }
        }

        System.out.print(sb.toString());
    }

    static boolean matches(Book book, String qTitle, String qAuthor, 
                          String qDateFrom, String qDateTo) {
        // Check title
        if (!qTitle.equals("*") && !book.title.contains(qTitle)) {
            return false;
        }
        // Check author
        if (!qAuthor.equals("*") && !book.author.contains(qAuthor)) {
            return false;
        }
        // Check date range
        if (!qDateFrom.equals("*") && book.date.compareTo(qDateFrom) < 0) {
            return false;
        }
        if (!qDateTo.equals("*") && book.date.compareTo(qDateTo) > 0) {
            return false;
        }
        return true;
    }

    static class Book {
        String title;
        String author;
        String date;

        Book(String title, String author, String date) {
            this.title = title;
            this.author = author;
            this.date = date;
        }
    }
}

