import java.io.*;
import java.util.*;

public class Main {
    static class Book {
        String title;
        String author;
        String date;
        Book(String title, String author, String date) {
            this.title = title;
            this.author = author;
            this.date = date;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        int n = Integer.parseInt(line.trim());

        List<Book> books = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String title = br.readLine();
            String author = br.readLine();
            String date = br.readLine();
            books.add(new Book(title, author, date));
        }

        int q = Integer.parseInt(br.readLine().trim());
        StringBuilder out = new StringBuilder();

        for (int qi = 0; qi < q; qi++) {
            String qTitle = br.readLine();
            String qAuthor = br.readLine();
            String qFrom = br.readLine();
            String qTo = br.readLine();

            if (qi > 0) out.append('\n');

            for (Book b : books) {
                if (matchString(b.title, qTitle)
                        && matchString(b.author, qAuthor)
                        && b.date.compareTo(qFrom) >= 0
                        && b.date.compareTo(qTo) <= 0) {
                    out.append(b.title).append('\n');
                }
            }
        }

        System.out.print(out.toString());
    }

    static boolean matchString(String s, String q) {
        if (q.equals("*")) return true;
        return s.contains(q);
    }
}
